import type { Message, RenderedMessage } from "../message-model"

const texts = {
 es: { confirmation: "Reserva confirmada", pending: "Reserva pendiente de confirmación", reminder: "Te recordamos tu reserva", cancellation: "Reserva cancelada", waitlist_offer: "Hay sitio para ti", deposit_request: "Completa la señal de tu reserva", review_request: "¿Cómo fue tu visita? Déjanos una reseña", confirm: "Confirmo", cancel: "Cancelar", guests: "personas", reference: "Referencia" },
 ca: { confirmation: "Reserva confirmada", pending: "Reserva pendent de confirmació", reminder: "Et recordem la teva reserva", cancellation: "Reserva cancel·lada", waitlist_offer: "Hi ha lloc per a tu", deposit_request: "Completa la paga i senyal de la reserva", review_request: "Com ha anat la visita? Deixa’ns una ressenya", confirm: "Confirmo", cancel: "Cancel·lar", guests: "persones", reference: "Referència" },
 en: { confirmation: "Booking confirmed", pending: "Booking awaiting confirmation", reminder: "A reminder of your booking", cancellation: "Booking cancelled", waitlist_offer: "A table is available for you", deposit_request: "Pay your booking deposit", review_request: "How was your visit? Leave us a review", confirm: "Confirm", cancel: "Cancel", guests: "guests", reference: "Reference" },
} as const
export type MessageButton = { id: "confirm" | "cancel"; title: string }
/** Datos compartidos: guestName, restaurantName, partySize, startAt, timezone,
 * reference, manageUrl, offerUrl, paymentUrl, googleReviewUrl. Acepta date/time de R1. */
export function renderMessage(message: Pick<Message, "template" | "language" | "channel" | "data">): RenderedMessage & { buttons: MessageButton[] } {
 const t = texts[message.language]
 const d = message.data
 const value = (key: string) => d[key] == null ? "" : String(d[key])
 const when = typeof d.startAt === "number" ? new Intl.DateTimeFormat(message.language, { timeZone: value("timezone") || "Europe/Madrid", dateStyle: "medium", timeStyle: "short" }).format(d.startAt) : [value("date"), value("time")].filter(Boolean).join(" ")
 const heading = t[message.template]
 const url = message.template === "review_request" ? value("googleReviewUrl") : message.template === "waitlist_offer" ? value("offerUrl") : message.template === "deposit_request" ? value("paymentUrl") || value("manageUrl") : value("manageUrl")
 const body = [heading, value("restaurantName"), value("guestName"), when, d.partySize ? `${d.partySize} ${t.guests}` : "", d.reference ? `${t.reference}: ${d.reference}` : "", url].filter(Boolean).join("\n")
 const buttons: MessageButton[] = message.channel === "whatsapp" && ["confirmation", "pending", "reminder"].includes(message.template) ? [{ id: "confirm", title: t.confirm }, { id: "cancel", title: t.cancel }] : []
 return { subject: message.channel === "email" ? heading : null, body, buttons }
}
